function F({registerIndicator:k,sourceValues:I,nulls:q}){k({id:"oa-vidya",name:"Variable Index Dynamic Average (VIDYA)",category:"Trends IIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"stdPeriod",type:"number",label:"Std Dev Period (0=use Period)",default:0,min:0,max:5e3,step:1,tooltip:"Window for the slower standard deviation. Zero falls back to Period."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"vidya",type:"line",title:"VIDYA",style:{color:"#ffeb3b",lineWidth:2}}],calc(r,s){const u=Math.max(1,Math.floor(Number(s.period)||10)),m=Math.max(0,Math.floor(Number(s.stdPeriod)||0)),f=I(r,s.source||"close"),A=2/(u+1),h=m>0?m:u,D=Math.max(h,5),p=new Array(r.length).fill(NaN);let i=NaN;for(let o=0;o<r.length;o++){const c=f[o];if(Number.isFinite(c)){let y=0,b=0,l=0,x=0,M=0,n=0;for(let e=0;e<D;e++){const N=o-e;if(N<0)continue;const t=f[N];Number.isFinite(t)&&(e<h&&(y+=t,b+=t*t,l+=1),e<5&&(x+=t,M+=t*t,n+=1))}let d=0;if(l>0){const e=y/l;d=Math.sqrt(Math.max(b/l-e*e,0))}let P=0;if(n>0){const e=x/n;P=Math.sqrt(Math.max(M/n-e*e,0))}let a=d>0?P/d:1;Number.isFinite(a)||(a=1),a=Math.min(Math.max(a,0),1);const v=A*a;i=Number.isFinite(i)?c*v+i*(1-v):c}p[o]=i}return{vidya:q(p)}}})}export{F as default};
